package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED. A clerk settling an OPEN claim whose due is above the
 * clerk limit sends it to PENDING instead, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN
 * or PENDING claim may be VOID; a steward may also void a SETTLED one shortly after its settlement (see ClaimService).
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to the next one by opening, settling or voiding it. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || isOpen();
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward claimed and the totals. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is handled as open: it goes overdue, bears the late charge, and a hold takes it out of the totals. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
-- A statement taken of a person: their due-total then (two decimals, or n/a), how many of their
-- claims counted, and the sheet's today when it was taken. A person's statements are in the order
-- of their ids; the last one is the person's last statement.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    taken_on  DATE         NOT NULL,
    due_total VARCHAR(20)  NOT NULL,
    claims    INT          NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);

-- Whether the claim is bound by its person's last statement, and the due it was bound to (null when
-- it had none then: n/a). A bound claim shows and totals that due until the next statement.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
-- A hold runs from its from-date to its to-date, both inclusive (no to-date: open-ended), and a person may have
-- several over time. Only the person's OPEN and PENDING claims dated within a hold, and not bound by a statement,
-- are left out of the live totals. A person held before keeps a hold from the beginning of time with no end.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE
);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A rate may carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it, with no later rate in force on its date, has no rate. Null: no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_after_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
-- The rate for each grade on a sheet: a percent with two decimals (0.00 or more). A grade with no
-- row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL,
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- Whether a period is soft-closed: its due-total and each person's due-total for it are fixed (closed_total and
-- period_person_total) as for a close, yet claims dated in it can still change. A period is never both closed and
-- soft-closed.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- Whether a claim was added while the period its date falls in was soft-closed.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;

